<?php $this->layout('default'); use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V; $r = H::report();
$kpi = static fn (string $l, string $v): string => '<div class="cms-kpi"><span>' . V::e($l) . '</span><strong>' . V::e($v) . '</strong></div>';
$table = static function (string $title, array $head, array $rows): string { $h = '<div class="cms-card"><h2>' . V::e($title) . '</h2>'; if ($rows === []) { return $h . V::empty('Sem dados ainda.') . '</div>'; } $h .= '<div class="cms-table-wrap"><table><thead><tr>'; foreach ($head as $i => $c) { $h .= '<th' . ($i ? ' class="num"' : '') . '>' . V::e($c) . '</th>'; } $h .= '</tr></thead><tbody>'; foreach ($rows as $row) { $h .= '<tr>'; foreach (array_values($row) as $i => $c) { $h .= '<td' . ($i ? ' class="num"' : '') . '>' . V::e($c) . '</td>'; } $h .= '</tr>'; } return $h . '</tbody></table></div></div>'; }; ?>
<div class="cms-kpis"><?= $kpi('Chamados', (string) $r['total']) . $kpi('Primeira resposta (média)', V::minutes($r['first_response_avg'])) . $kpi('Resolução (média)', V::minutes($r['resolution_avg'])) . $kpi('Vencidos', (string) $r['overdue']) . $kpi('Reabertos', (string) $r['reopened']) ?></div>
<?= $table('Por situação', ['Situação', 'Chamados'], array_map(static fn ($x) => [V::TICKET_STATUS[$x['status']] ?? $x['status'], $x['total']], $r['by_status'])) ?><?= $table('Por categoria', ['Categoria', 'Chamados'], $r['by_category']) ?><?= $table('Por atendente', ['Atendente', 'Chamados', 'Resolvidos'], $r['by_agent']) ?><?= $table('Avaliações', ['Avaliação', 'Total'], array_map(static fn ($x) => [V::RATINGS[$x['rating']] ?? $x['rating'], $x['total']], $r['ratings'])) ?>
